open(base+'/lib.py','w').write('''from collections import Counter

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def uniform_rows(grid):
    """Indices of rows that are one color throughout."""
    return [i for i, row in enumerate(grid) if len(set(row)) == 1]

def uniform_cols(grid):
    """Indices of columns that are one color throughout."""
    h, w = len(grid), len(grid[0])
    return [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]

def divider_lines(grid):
    """Full rows and columns that are one non-background color throughout: (row indices, col indices)."""
    bg = background(grid)
    return ([i for i in uniform_rows(grid) if grid[i][0] != bg],
            [j for j in uniform_cols(grid) if grid[0][j] != bg])

def segments(dividers, size):
    """Maximal runs of indices between divider lines, as (start, end) pairs."""
    segs, start = [], 0
    for d in dividers + [size]:
        if d > start:
            segs.append((start, d))
        start = d + 1
    return segs

def tile_pattern_into_empty(grid):
    """Copy the pattern block into every all-background block of a grid split by divider lines."""
    rows, cols = divider_lines(grid)
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    blocks = [(r0, r1, c0, c1)
              for r0, r1 in segments(rows, h)
              for c0, c1 in segments(cols, w)]
    src = next(([row[c0:c1] for row in grid[r0:r1]]
                for r0, r1, c0, c1 in blocks
                if any(v != bg for row in grid[r0:r1] for v in row[c0:c1])), None)
    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in blocks:
        if all(v == bg for row in grid[r0:r1] for v in row[c0:c1]) and src:
            for i, srow in enumerate(src):
                out[r0+i][c0:c1] = srow
    return out
''')
